ALTER TABLE public.campaigns ADD COLUMN IF NOT EXISTS target_audience jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS settings jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.ads ADD COLUMN IF NOT EXISTS campaign_id uuid REFERENCES public.campaigns(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS canvas_data jsonb, ADD COLUMN IF NOT EXISTS name text NOT NULL DEFAULT 'Untitled Creative', ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'draft';
CREATE INDEX IF NOT EXISTS ads_campaign_user_idx ON public.ads(campaign_id,user_id);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ads TO authenticated;
GRANT ALL ON public.ads TO service_role;
CREATE OR REPLACE FUNCTION public.validate_ad_campaign_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.campaign_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.campaigns c WHERE c.id=NEW.campaign_id AND c.user_id=NEW.user_id) THEN RAISE EXCEPTION 'Creative and campaign must have the same owner'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ads_validate_campaign_owner BEFORE INSERT OR UPDATE ON public.ads FOR EACH ROW EXECUTE FUNCTION public.validate_ad_campaign_owner();
CREATE TABLE public.campaign_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE, user_id uuid NOT NULL, ad_id uuid NOT NULL UNIQUE REFERENCES public.ads(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.campaign_assets TO authenticated;
GRANT ALL ON public.campaign_assets TO service_role;
ALTER TABLE public.campaign_assets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage creative links" ON public.campaign_assets FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.ads a WHERE a.id=ad_id AND a.user_id=auth.uid() AND a.campaign_id=campaign_assets.campaign_id));
CREATE TRIGGER campaign_assets_updated BEFORE UPDATE ON public.campaign_assets FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE OR REPLACE FUNCTION public.sync_ad_campaign_asset() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN DELETE FROM public.campaign_assets WHERE ad_id=NEW.id; IF NEW.campaign_id IS NOT NULL THEN INSERT INTO public.campaign_assets(campaign_id,user_id,ad_id) VALUES(NEW.campaign_id,NEW.user_id,NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER ads_sync_campaign_asset AFTER INSERT OR UPDATE OF campaign_id ON public.ads FOR EACH ROW EXECUTE FUNCTION public.sync_ad_campaign_asset();
CREATE OR REPLACE FUNCTION public.duplicate_campaign(p_campaign_id uuid) RETURNS public.campaigns LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE source public.campaigns; result public.campaigns; BEGIN SELECT * INTO source FROM public.campaigns WHERE id=p_campaign_id AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; INSERT INTO public.campaigns(user_id,name,status,platform,budget,objective,start_date,end_date,target_audience,settings) VALUES(auth.uid(),source.name||' (Copy)','draft',source.platform,source.budget,source.objective,source.start_date,source.end_date,source.target_audience,source.settings) RETURNING * INTO result; INSERT INTO public.ads(user_id,campaign_id,template_id,content,preview_url,canvas_data,name,status) SELECT auth.uid(),result.id,template_id,content,preview_url,canvas_data,name,'draft' FROM public.ads WHERE campaign_id=source.id AND user_id=auth.uid(); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.duplicate_campaign(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.duplicate_campaign(uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.validate_ad_campaign_owner() FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.sync_ad_campaign_asset() FROM PUBLIC,anon;